import { request } from 'undici';

export interface ApiResponse {
  [key: string]: unknown;
}

export async function fetchJson(url: string): Promise<ApiResponse> {
  const { statusCode, body } = await request(url);
  if (statusCode >= 400) {
    throw new Error(`HTTP ${statusCode}`);
  }
  return (await body.json()) as ApiResponse;
}
